class Solution {
public:
    int maxAncestorDiff(TreeNode* root) {
        int ans = 0;
        dfs(root, root->val, root->val, ans);
        return ans;
    }
private:
    void dfs(TreeNode* node, int mn, int mx, int& ans) {
        if (!node) return;
        int d1 = node->val - mn;
        if (d1 < 0) d1 = -d1;
        int d2 = node->val - mx;
        if (d2 < 0) d2 = -d2;
        if (d1 > ans) ans = d1;
        if (d2 > ans) ans = d2;
        if (node->val < mn) mn = node->val;
        if (node->val > mx) mx = node->val;
        dfs(node->left, mn, mx, ans);
        dfs(node->right, mn, mx, ans);
    }
};
